{
    char *data;
    int i;
    int rows;

    data = malloc(2048);
    data[0] = 0;
    for (i = 1; i < 6; i++)
        if (p->ccc[i - 1] > 0)
            sprintf(data, "%sClock Challenge %d:  %7d\n", data, i,
                    p->ccc[i - 1]);
    if (p->ccc[0] > 0)
        sprintf(data, "%s\n", data);
    for (i = 1; i < 6; i++)
        if (p->ccc[i - 1] > 0 && p->cccNum[i - 1] > 0)
            sprintf(data, "%sAverage CC %d:       %7d\n", data, i,
                    p->cccTotal[i - 1] / p->cccNum[i - 1]);
    if (p->cccTotal[0] > 0)
        sprintf(data, "%s\n", data);
    rows = 0;
    for (i = 0; i < 10; i++)
        if (p->rewards[i] > 0) {
            sprintf(data, "%s%-12s        %7d\n", data, comboNames[i],
                    p->rewards[i]);
            rows++;
        }
    if (rows)
        sprintf(data, "%s\n", data);
    return data;
}

